package za.ac.cput.service; import org.springframework.stereotype.Service; import za.ac.cput.domain.Login; import za.ac.cput.repository.LoginRepository; @Service public class LoginServiceImpl implements LoginService{private final LoginRepository repository; public LoginServiceImpl(LoginRepository repository){this.repository=repository;} public Login create(Login x){return repository.save(x);} public Login read(String id){return repository.findById(id).orElse(null);} public Login update(Login x){return repository.save(x);} public boolean delete(String id){if(repository.existsById(id)){repository.deleteById(id);return true;}return false;} public java.util.List<Login> findAll(){return repository.findAll();} }